<template>
  <q-slide-transition>
    <div v-show="selectedCount > 0" class="bulk-action-bar">
      <div class="bulk-action-bar__content">
        <!-- Selection Info -->
        <div class="bulk-action-bar__info">
          <q-icon name="check_circle" color="primary" size="sm" />
          <span class="text-weight-medium">
            {{ selectedCount }} {{ $t('scripts_selected') }}
          </span>
        </div>

        <!-- Action Buttons -->
        <div class="bulk-action-bar__actions">
          <q-btn
            outline
            dense
            icon="check_circle"
            :label="$t('activate')"
            color="positive"
            @click="$emit('bulk-activate')"
            :disable="processing"
          >
            <q-tooltip>{{ $t('activate_selected_scripts') }}</q-tooltip>
          </q-btn>

          <q-btn
            outline
            dense
            icon="cancel"
            :label="$t('deactivate')"
            color="warning"
            @click="$emit('bulk-deactivate')"
            :disable="processing"
          >
            <q-tooltip>{{ $t('deactivate_selected_scripts') }}</q-tooltip>
          </q-btn>

          <q-btn
            outline
            dense
            icon="content_copy"
            :label="$t('copy')"
            color="primary"
            @click="$emit('bulk-copy')"
            :disable="processing"
          >
            <q-tooltip>{{ $t('copy_selected_scripts') }}</q-tooltip>
          </q-btn>

          <q-btn
            outline
            dense
            icon="download"
            :label="$t('export')"
            color="primary"
            @click="$emit('bulk-export')"
            :disable="processing"
          >
            <q-tooltip>{{ $t('export_selected_scripts') }}</q-tooltip>
          </q-btn>

          <q-separator vertical inset class="q-mx-sm" />

          <q-btn
            outline
            dense
            icon="delete"
            :label="$t('delete')"
            color="negative"
            @click="confirmBulkDelete"
            :disable="processing || hasStandardScriptsSelected"
          >
            <q-tooltip v-if="hasStandardScriptsSelected">
              {{ $t('cannot_delete_standard_scripts') }}
            </q-tooltip>
            <q-tooltip v-else>{{ $t('delete_selected_scripts') }}</q-tooltip>
          </q-btn>
        </div>

        <!-- Cancel Button -->
        <q-btn
          flat
          dense
          icon="close"
          :label="$t('cancel')"
          color="grey-7"
          @click="$emit('cancel')"
          :disable="processing"
        />
      </div>

      <!-- Loading Overlay -->
      <q-inner-loading :showing="processing">
        <q-spinner-dots size="50px" color="primary" />
      </q-inner-loading>
    </div>
  </q-slide-transition>

  <!-- Delete Confirmation Dialog -->
  <q-dialog v-model="showDeleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row items-center"
        style="justify-content: center; display: flex"
      >
        <q-avatar
          icon="warning"
          color="negative"
          text-color="white"
          size="56px"
        />
      </q-card-section>

      <q-card-section class="text-center">
        <div class="text-h6 text-weight-bold q-mb-sm">
          {{ $t('confirm_bulk_delete_title') }}
        </div>
        <div class="text-body2">
          {{ $t('confirm_bulk_delete_message', { count: selectedCount }) }}
        </div>
        <div class="text-body2 text-grey-7 q-mt-sm">
          {{ $t('this_action_cannot_be_undone') }}
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          color="grey-7"
          v-close-popup
          :disable="processing"
        />
        <q-btn
          unelevated
          :label="$t('delete')"
          color="negative"
          @click="handleBulkDelete"
          :loading="processing"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  name: 'BulkActionBar',
  props: {
    selectedCount: {
      type: Number,
      required: true,
    },
    processing: {
      type: Boolean,
      default: false,
    },
    hasStandardScriptsSelected: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    'bulk-activate',
    'bulk-deactivate',
    'bulk-copy',
    'bulk-export',
    'bulk-delete',
    'cancel',
  ],
  setup(props, { emit }) {
    const showDeleteConfirm = ref(false);

    const confirmBulkDelete = () => {
      showDeleteConfirm.value = true;
    };

    const handleBulkDelete = () => {
      emit('bulk-delete');
      showDeleteConfirm.value = false;
    };

    return {
      showDeleteConfirm,
      confirmBulkDelete,
      handleBulkDelete,
    };
  },
});
</script>

