<template>
  <q-item
    clickable
    class="script-card"
    :class="[
      `script-card--${statusClass}`,
      {
        'script-card--selected': isSelected,
        'script-card--hovering': isHovering,
      },
    ]"
    @click="handleCardClick"
    @mouseenter="isHovering = true"
    @mouseleave="isHovering = false"
  >
    <!-- Selection Checkbox -->
    <q-item-section side v-if="selectionMode">
      <q-checkbox
        v-model="selected"
        @update:model-value="$emit('update:selected', $event)"
        @click.stop
        color="primary"
        :aria-label="`Select ${script.label}`"
      />
    </q-item-section>

    <!-- Script Icon -->
    <q-item-section avatar>
      <q-avatar
        :icon="scriptIcon"
        :color="statusColor"
        text-color="white"
        size="28px"
      />
    </q-item-section>

    <!-- Main Content -->
    <q-item-section>
      <!-- Header: Name + Quick Actions -->
      <div class="script-card__header">
        <div class="script-card__name">
          {{ script.label || $t('untitled_script') }}

          <!-- Standard Badge -->
          <q-badge
            v-if="isDefaultOrg(script.org_id)"
            color="orange"
            text-color="white"
            class="q-ml-sm"
            :label="$t('standard')"
          />
        </div>

      </div>

      <!-- Metadata Row: Chips + Dates -->
      <div class="script-card__metadata">
        <!-- Only show sub doc type if it exists (more specific than main doc type) -->
        <q-chip
          v-if="subDocTypeLabel"
          size="sm"
          color="grey-3"
          text-color="grey-8"
          icon="description"
          :label="subDocTypeLabel"
        />

        <!-- Trigger Chip -->
        <q-chip
          size="sm"
          color="primary"
          text-color="white"
          icon="bolt"
          :label="triggerLabel"
        />

        <!-- Version Chip -->
        <q-chip
          size="sm"
          color="purple-2"
          text-color="purple-9"
          icon="history"
          :label="`v${script.version || 0}`"
        />

        <!-- Dates inline -->
        <span class="script-card__date-info">
          <q-icon name="add_circle" size="14px" color="grey-6" />
          <span class="text-caption text-grey-7">{{ createdInfo || 'N/A' }}</span>
          <q-tooltip>{{ $t('created') }}</q-tooltip>
        </span>

        <span class="script-card__date-info">
          <q-icon name="edit" size="14px" color="grey-6" />
          <span class="text-caption text-grey-7">{{ updatedInfo || 'N/A' }}</span>
          <q-tooltip>{{ $t('last_modified_on') }}</q-tooltip>
        </span>
      </div>
    </q-item-section>

    <!-- Actions & Status Section -->
    <q-item-section side>
      <div class="script-card__actions-row">
        <!-- Quick Actions -->
        <q-btn
          flat
          dense
          round
          icon="edit"
          color="primary"
          size="sm"
          @click.stop="$emit('edit', script)"
          :aria-label="$t('edit')"
        >
          <q-tooltip>{{ $t('edit') }}</q-tooltip>
        </q-btn>

        <q-btn
          flat
          dense
          round
          icon="content_copy"
          color="grey-7"
          size="sm"
          @click.stop="$emit('copy', script)"
          :aria-label="$t('copy')"
        >
          <q-tooltip>{{ $t('copy_script') }}</q-tooltip>
        </q-btn>

        <q-btn
          v-if="!isDefaultOrg(script.org_id)"
          flat
          dense
          round
          icon="delete"
          color="negative"
          size="sm"
          @click.stop="$emit('delete', script)"
          :aria-label="$t('delete')"
        >
          <q-tooltip>{{ $t('delete') }}</q-tooltip>
        </q-btn>

        <!-- Status Toggle -->
        <f-toggle
          size="xs"
          :model-value="script.is_active"
          @update:model-value="$emit('toggle-status', script, $event)"
          @click.stop
          color="positive"
          :label="script.is_active ? $t('active') : $t('inactive')"
          :aria-label="`${script.is_active ? $t('deactivate') : $t('activate')} ${script.label}`"
          class="q-ml-sm"
        />
      </div>
    </q-item-section>
  </q-item>
</template>

<script lang="ts">
import { i18n } from 'src/boot/i18n';
import { defineComponent } from 'vue';
import dateUtils from 'src/utils/date';
import { isDefaultOrg } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  name: 'ScriptCard',
  props: {
    script: {
      type: Object as () => dynamicObj,
      required: true,
    },
    selected: {
      type: Boolean,
      default: false,
    },
    selectionMode: {
      type: Boolean,
      default: false,
    },
    docTypeList: {
      type: Array,
      default: () => [],
    },
  },
  emits: [
    'click',
    'edit',
    'copy',
    'duplicate',
    'export',
    'delete',
    'toggle-status',
    'quick-view',
    'version-history',
    'update:selected',
  ],
  data() {
    return {
      isHovering: false,
    };
  },
  computed: {
    isMobile(): boolean {
      return this.$q.screen.lt.sm;
    },
    isSelected(): boolean {
      return this.selected;
    },
    statusClass(): string {
      return this.script.is_active ? 'active' : 'inactive';
    },
    statusColor(): string {
      return this.script.is_active ? 'positive' : 'negative';
    },
    statusLabel(): string {
      return this.script.is_active ? 'Active' : 'Inactive';
    },
    scriptIcon(): string {
      const language = this.script.script_language?.toLowerCase() || 'python';
      const iconMap: Record<string, string> = {
        python: 'code',
        javascript: 'javascript',
        typescript: 'code',
        default: 'code',
      };
      return iconMap[language] || iconMap.default;
    },
    scriptLanguage(): string {
      return this.script.script_language || 'Python';
    },
    docTypeLabel(): string {
      const docType = this.docTypeList.find(
        (item: any) => item.value === this.script.doc_type,
      ) as dynamicObj;
      return docType
        ? String(docType.label)
        : String(this.script.doc_type || 'N/A');
    },
    subDocTypeLabel(): string {
      if (!this.script.sub_doc_type || this.script.sub_doc_type === 'null') {
        return '';
      }
      const subDocType = this.docTypeList.find(
        (item: any) => item.value === this.script.sub_doc_type,
      ) as dynamicObj;
      return subDocType
        ? String(subDocType.label)
        : String(this.script.sub_doc_type);
    },
    triggerLabel(): string {
      const trigger = this.script.trigger_on || 'ALL';
      return i18n.t(`script.${trigger}`.toLowerCase());
    },
    hasVersions(): boolean {
      return !!(this.script.version && this.script.version > 0);
    },
    createdInfo(): string | null {
      const date = this.formatDateTime(this.script.created_on);
      const user = this.script.created_by;

      if (date && user) return `${date} by ${user}`;
      if (date) return date;
      return null;
    },
    updatedInfo(): string | null {
      const date = this.formatDateTime(this.script.last_modified_on);
      const user = this.script.last_modified_by;

      if (date && user) return `${date} by ${user}`;
      if (date) return date;
      return null;
    },
  },
  methods: {
    isDefaultOrg,
    formatDateTime(dateString: string | null | undefined): string | null {
      if (!dateString) return null;
      const result = dateUtils.methods.formatDateTimeZone(dateString);
      return result === '-' ? null : result;
    },
    formatRelativeTime(dateString: string | null | undefined): string | null {
      if (!dateString) return null;

      try {
        const date = new Date(dateString);
        const now = new Date();
        const diffMs = now.getTime() - date.getTime();
        const diffMins = Math.floor(diffMs / 60000);
        const diffHours = Math.floor(diffMins / 60);
        const diffDays = Math.floor(diffHours / 24);

        if (diffMins < 1) return 'just now';
        if (diffMins < 60)
          return `${diffMins} min${diffMins > 1 ? 's' : ''} ago`;
        if (diffHours < 24)
          return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
        if (diffDays < 7)
          return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;

        return date.toLocaleDateString();
      } catch (e) {
        return null;
      }
    },
    handleCardClick() {
      if (this.selectionMode) {
        this.$emit('update:selected', !this.selected);
      } else {
        this.$emit('click', this.script);
      }
    },
  },
});
</script>

