<template>
  <div class="scripts-page page-height-limit">
    <div class="scripts-page__content">
      <!-- Sticky Header: Filter -->
      <div class="scripts-page__sticky-header">
        <!-- Search & Filter Bar -->
        <div>
          <SearchFilterBar
        v-model="searchQuery"
        :quick-filter="quickFilter"
        :filters="advancedFilters"
        :doc-type-options="doc_types_sub_types_list"
        :total-count="totalCount"
        :active-count="activeCount"
        :inactive-count="inactiveCount"
        :sort-by="sortBy"
        :sort-options="sortOptions"
        @update:quick-filter="quickFilter = $event"
        @update:filters="advancedFilters = $event"
        @update:sort-by="sortBy = $event"
        @create-new="addNewRecord"
          />
        </div>
      </div>

      <!-- Scripts List -->
      <div class="scripts-list-container">
        <!-- Loading Skeletons -->
        <q-list
          v-if="processing && display_script.length === 0"
          bordered
          class="scripts-list"
        >
          <ScriptCardSkeleton v-for="n in 5" :key="n" />
        </q-list>

        <!-- Script Cards -->
        <q-list
          v-else-if="filteredScripts.length > 0"
          bordered
          class="scripts-list"
        >
          <ScriptCard
            v-for="script in filteredScripts"
            :key="script.id"
            :script="script"
            :selected="selectedScripts.includes(script.id)"
            :selection-mode="selectionMode"
            :doc-type-list="doc_types_sub_types_list"
            @click="editRecord(script)"
            @edit="editRecord(script)"
            @copy="copyScriptClicked(script)"
            @duplicate="copyScriptClicked(script)"
            @export="exportScript(script)"
            @delete="confirmDelete(script)"
            @toggle-status="handleToggleStatus"
            @quick-view="quickViewScript(script)"
            @version-history="viewVersionHistory(script)"
            @update:selected="toggleSelection(script.id)"
          />
        </q-list>

        <!-- Enhanced Empty State -->
        <EnhancedEmptyState
          v-else
          :icon="hasSearchOrFilter ? 'search_off' : 'description'"
          :icon-color="hasSearchOrFilter ? 'grey-5' : 'primary'"
          :title="emptyStateTitle"
          :description="emptyStateDescription"
          :show-action="!hasSearchOrFilter"
          :action-icon="'add'"
          :action-label="$t('create_script')"
          :show-help="!hasSearchOrFilter"
          :help-text="$t('learn_more_about_scripts')"
          help-link-name="scripts"
          @action-click="addNewRecord"
        />
      </div>
    </div>

    <!-- Bulk Action Bar -->
    <BulkActionBar
      :selected-count="selectedScripts.length"
      :processing="bulkProcessing"
      :has-standard-scripts-selected="hasStandardScriptsSelected"
      @bulk-activate="bulkActivate"
      @bulk-deactivate="bulkDeactivate"
      @bulk-copy="bulkCopy"
      @bulk-export="bulkExport"
      @bulk-delete="bulkDelete"
      @cancel="cancelSelection"
    />

    <!-- Loader -->
    <Loader />

    <!-- Copy Script Dialog -->
    <q-dialog
      v-model="scriptCopyDialog"
      persistent
      @keydown.esc="resetCopyDialog"
    >
      <q-card style="width: 600px; max-width: 600px; height: 240px">
        <q-toolbar class="text-white secondary-toolbar">
          <q-toolbar-title>
            <span class="text-weight-bold">{{ $t('copy') }}</span>
          </q-toolbar-title>
          <q-btn flat round dense icon="close" @click="resetCopyDialog" />
        </q-toolbar>

        <q-card-section>
          <div class="row q-mt-md">
            <div class="col-12">
              <q-input
                v-model="copyLabel"
                :label="$t('label')"
                outlined
                class="full q-ml-sm"
              />
            </div>
          </div>
        </q-card-section>

        <q-card-section class="p-t-0">
          <div class="row q-mt-md">
            <div class="col-12">
              <q-btn
                color="primary"
                class="q-ml-sm float-right"
                :label="$t('copy')"
                @click="copyRecord"
              />

              <q-btn
                class="float-right highlighted-back"
                :label="$t('cancel')"
                @click="resetCopyDialog"
              />
            </div>
          </div>
        </q-card-section>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="deleteConfirmation" persistent>
      <q-card>
        <q-card-section
          class="row"
          style="justify-content: center; display: flex"
        >
          <q-avatar icon="warning" color="primary" text-color="white" />
        </q-card-section>

        <q-card-section class="row items-center">
          <span class="q-ml-sm">{{ $t('export_sure') }}</span>
        </q-card-section>

        <q-card-actions align="right">
          <q-btn
            flat
            :label="$t('cancel')"
            data-cy="cancel-card"
            color="primary"
            v-close-popup
          />
          <q-btn
            flat
            :label="$t('delete')"
            data-cy="done-card"
            color="primary"
            v-close-popup
            @click="deleteRecord()"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref, computed } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import SearchFilterBar from 'src/pages/Settings/Components/Scripts/SearchFilterBar.vue';
import ScriptCard from 'src/pages/Settings/Components/Scripts/ScriptCard.vue';
import BulkActionBar from 'src/pages/Settings/Components/Scripts/BulkActionBar.vue';
import EnhancedEmptyState from 'src/pages/Settings/Components/Scripts/EnhancedEmptyState.vue';
import ScriptCardSkeleton from 'src/pages/Settings/Components/Scripts/ScriptCardSkeleton.vue';
import { useScriptsStore, useDropdownStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { docScriptApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { DEFAULT_ORG_UUID } from 'src/constants';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, displayFieldLabel],
  components: {
    
    Loader,
    SearchFilterBar,
    ScriptCard,
    BulkActionBar,
    EnhancedEmptyState,
    ScriptCardSkeleton,
  },
  data() {
    return {
      searchQuery: '',
      quickFilter: 'all',
      sortBy: 'modified-desc',
      advancedFilters: {
        docTypes: [],
        triggers: [],
        languages: [],
        dateFrom: null,
        dateTo: null,
      } as {
        docTypes: string[];
        triggers: string[];
        languages: string[];
        dateFrom: string | null;
        dateTo: string | null;
      },
      selectedScripts: [] as string[],
      selectionMode: false,
      bulkProcessing: false,
      display_script: [] as dynamicObj[],
      copyLabel: '',
      copyScriptId: '',
    };
  },
  computed: {
    sortOptions() {
      return [
        {
          label: this.$t('sort_name_asc'),
          value: 'name-asc',
          text: 'A-Z',
        },
        {
          label: this.$t('sort_name_desc'),
          value: 'name-desc',
          text: 'Z-A',
        },
        {
          label: this.$t('sort_modified_newest'),
          value: 'modified-desc',
          icon: 'update',
        },
        {
          label: this.$t('sort_modified_oldest'),
          value: 'modified-asc',
          icon: 'history',
        },
      ];
    },

    filteredScripts(): dynamicObj[] {
      let filtered = [...this.display_script];

      // Quick filter (Active/Inactive/All)
      if (this.quickFilter === 'active') {
        filtered = filtered.filter((script: dynamicObj) => script.is_active);
      } else if (this.quickFilter === 'inactive') {
        filtered = filtered.filter((script: dynamicObj) => !script.is_active);
      }

      // Search query
      if (this.searchQuery) {
        const query = this.searchQuery.toLowerCase();
        filtered = filtered.filter((script: dynamicObj) => {
          return (
            script.label?.toLowerCase().includes(query) ||
            script.doc_type?.toLowerCase().includes(query) ||
            script.sub_doc_type?.toLowerCase().includes(query) ||
            script.trigger_on?.toLowerCase().includes(query)
          );
        });
      }

      // Advanced filters
      if (this.advancedFilters.docTypes.length > 0) {
        filtered = filtered.filter((script: dynamicObj) =>
          this.advancedFilters.docTypes.includes(script.doc_type),
        );
      }

      if (this.advancedFilters.triggers.length > 0) {
        filtered = filtered.filter((script: dynamicObj) =>
          this.advancedFilters.triggers.includes(script.trigger_on),
        );
      }

      // Date range filter
      if (this.advancedFilters.dateFrom) {
        const fromDate = new Date(this.advancedFilters.dateFrom);
        filtered = filtered.filter((script: dynamicObj) => {
          const dateField = script.last_modified_on || script.created_on;
          if (!dateField) return true;
          const scriptDate = new Date(dateField);
          return scriptDate >= fromDate;
        });
      }

      if (this.advancedFilters.dateTo) {
        const toDate = new Date(this.advancedFilters.dateTo);
        filtered = filtered.filter((script: dynamicObj) => {
          const dateField = script.last_modified_on || script.created_on;
          if (!dateField) return true;
          const scriptDate = new Date(dateField);
          return scriptDate <= toDate;
        });
      }

      // Sorting
      filtered.sort((a: dynamicObj, b: dynamicObj) => {
        switch (this.sortBy) {
          case 'name-asc':
            return (a.label || '').localeCompare(b.label || '');
          case 'name-desc':
            return (b.label || '').localeCompare(a.label || '');
          case 'modified-desc': {
            const aDate = new Date(a.last_modified_on || a.created_on || 0).getTime();
            const bDate = new Date(b.last_modified_on || b.created_on || 0).getTime();
            return bDate - aDate; // Newest first
          }
          case 'modified-asc': {
            const aDate = new Date(a.last_modified_on || a.created_on || 0).getTime();
            const bDate = new Date(b.last_modified_on || b.created_on || 0).getTime();
            return aDate - bDate; // Oldest first
          }
          default:
            return 0;
        }
      });

      return filtered;
    },

    totalCount(): number {
      return this.display_script.length;
    },

    activeCount(): number {
      return this.display_script.filter(
        (script: dynamicObj) => script.is_active,
      ).length;
    },

    inactiveCount(): number {
      return this.display_script.filter(
        (script: dynamicObj) => !script.is_active,
      ).length;
    },

    hasSearchOrFilter(): boolean {
      return (
        this.searchQuery !== '' ||
        this.advancedFilters.docTypes.length > 0 ||
        this.advancedFilters.triggers.length > 0 ||
        this.advancedFilters.dateFrom !== null ||
        this.advancedFilters.dateTo !== null
      );
    },

    emptyStateTitle(): string {
      if (this.hasSearchOrFilter) {
        return this.$t('no_scripts_found');
      }
      return this.$t('no_scripts_yet');
    },

    emptyStateDescription(): string {
      if (this.hasSearchOrFilter) {
        return this.$t('no_scripts_match_filters');
      }
      return this.$t('scripts_help_automate_description');
    },

    hasStandardScriptsSelected(): boolean {
      return this.selectedScripts.some((scriptId: string) => {
        const script = this.display_script.find(
          (s: dynamicObj) => s.id === scriptId,
        );
        return script?.org_id === DEFAULT_ORG_UUID;
      });
    },
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
    selectedScripts: {
      handler: function (newVal) {
        this.selectionMode = newVal.length > 0;
      },
    },
  },
  async mounted() {
    this.processing = true;
    this.fillDocTypeAndSubTypesListIfEmpty();
    await this.getList();
    this.processing = false;
  },
  methods: {
    async getList() {
      this.doc_type_key = String(this.$route.params.doc_type || '');
      this.sub_doc_type_key = String(this.$route.params.sub_doc_type || '');
      const response = await this.getScripts(
        this.doc_type_key,
        this.sub_doc_type_key,
      );
      if (response && Array.isArray(response)) {
        this.display_script = response;
      }
    },

    editRecord(record: dynamicObj) {
      const subPath = this.sub_doc_type_key ? `/${this.sub_doc_type_key}` : '';
      this.$router.push({
        path: `/settings/record-script/${this.doc_type_key}${subPath}`,
        query: {
          id: record.id,
        },
      });
    },

    addNewRecord() {
      const subPath = this.sub_doc_type_key ? `/${this.sub_doc_type_key}` : '';
      const url = '/settings/record-script/' + this.doc_type_key + subPath;
      this.$router.push(url);
    },

    copyScriptClicked(record: dynamicObj) {
      this.copyScriptId = record.id;
      this.copyLabel = `${record.label} (Copy)`;
      this.scriptCopyDialog = true;
    },

    resetCopyDialog() {
      this.copyScriptId = '';
      this.copyLabel = '';
      this.scriptCopyDialog = false;
    },

    async copyRecord() {
      try {
        this.processing = true;
        const data = {
          id: this.copyScriptId,
          label: this.copyLabel,
        } as dynamicObj;
        await docScriptApiService.copyScript(data);
        await this.getList();
        this.resetCopyDialog();
        notify.success(this.$t('record_copy_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.processing = false;
      }
    },

    confirmDelete(record: dynamicObj) {
      this.configId = record.id;
      this.deleteConfirmation = true;
    },

    async deleteRecord() {
      try {
        this.processing = true;
        await docScriptApiService.deleteRecord(this.configId.toString());
        this.getList();
        notify.success(this.$t('operation_sucessfull'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.deleteConfirmation = false;
        this.processing = false;
      }
    },

    async handleToggleStatus(script: dynamicObj, isActive: boolean) {
      try {
        this.processing = true;
        const response = await docScriptApiService.updateActive(
          script.id.toString(),
          isActive,
        );
        if (!response.success || response.success !== true) {
          throw { message: response.message };
        }

        script.is_active = isActive;
        notify.success(
          isActive
            ? this.$t('script_activated')
            : this.$t('script_deactivated'),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.processing = false;
      }
    },

    exportScript(script: dynamicObj) {
      // TODO: Implement export functionality
      console.log('Export script:', script);
      notify.success(this.$t('export_coming_soon'));
    },

    quickViewScript(script: dynamicObj) {
      // TODO: Implement quick view modal
      console.log('Quick view script:', script);
      notify.success(this.$t('quick_view_coming_soon'));
    },

    viewVersionHistory(script: dynamicObj) {
      // Navigate to script editor and open version history
      this.editRecord(script);
    },

    toggleSelection(scriptId: string) {
      const index = this.selectedScripts.indexOf(scriptId);
      if (index > -1) {
        this.selectedScripts.splice(index, 1);
      } else {
        this.selectedScripts.push(scriptId);
      }
    },

    cancelSelection() {
      this.selectedScripts = [];
    },

    async bulkActivate() {
      try {
        this.bulkProcessing = true;
        const promises = this.selectedScripts.map((scriptId: string) => {
          return docScriptApiService.updateActive(scriptId, true);
        });

        await Promise.all(promises);

        // Update local state
        this.display_script.forEach((script: dynamicObj) => {
          if (this.selectedScripts.includes(script.id)) {
            script.is_active = true;
          }
        });

        notify.success(
          this.$t('scripts_activated_successfully', {
            count: this.selectedScripts.length,
          }),
        );
        this.cancelSelection();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.bulkProcessing = false;
      }
    },

    async bulkDeactivate() {
      try {
        this.bulkProcessing = true;
        const promises = this.selectedScripts.map((scriptId: string) => {
          return docScriptApiService.updateActive(scriptId, false);
        });

        await Promise.all(promises);

        // Update local state
        this.display_script.forEach((script: dynamicObj) => {
          if (this.selectedScripts.includes(script.id)) {
            script.is_active = false;
          }
        });

        notify.success(
          this.$t('scripts_deactivated_successfully', {
            count: this.selectedScripts.length,
          }),
        );
        this.cancelSelection();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.bulkProcessing = false;
      }
    },

    async bulkCopy() {
      try {
        this.bulkProcessing = true;
        const promises = this.selectedScripts.map((scriptId: string) => {
          const script = this.display_script.find(
            (s: dynamicObj) => s.id === scriptId,
          );
          if (!script) return Promise.resolve();
          return docScriptApiService.copyScript({
            id: scriptId,
            label: `${script.label} (Copy)`,
          });
        });

        await Promise.all(promises);
        await this.getList();

        notify.success(
          this.$t('scripts_copied_successfully', {
            count: this.selectedScripts.length,
          }),
        );
        this.cancelSelection();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.bulkProcessing = false;
      }
    },

    bulkExport() {
      // TODO: Implement bulk export
      console.log('Bulk export:', this.selectedScripts);
      notify.success(this.$t('export_coming_soon'));
    },

    async bulkDelete() {
      // Filter out standard scripts
      const deletableScripts = this.selectedScripts.filter(
        (scriptId: string) => {
          const script = this.display_script.find(
            (s: dynamicObj) => s.id === scriptId,
          );
          return script?.org_id !== DEFAULT_ORG_UUID;
        },
      );

      if (deletableScripts.length === 0) {
        notify.error(this.$t('cannot_delete_standard_scripts'));
        return;
      }

      try {
        this.bulkProcessing = true;
        const promises = deletableScripts.map((scriptId: string) => {
          return docScriptApiService.deleteRecord(scriptId);
        });

        await Promise.all(promises);
        await this.getList();

        notify.success(
          this.$t('scripts_deleted_successfully', {
            count: deletableScripts.length,
          }),
        );
        this.cancelSelection();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.bulkProcessing = false;
      }
    },
  },
  setup() {
    const scrips_store = useScriptsStore();
    const { getScripts } = scrips_store;
    const {
      script_list,
      processing,
      doc_type_key,
      sub_doc_type_key,
      selected_record,
    } = storeToRefs(scrips_store);

    const dropdown_store = useDropdownStore();
    const { fillDocTypeAndSubTypesListIfEmpty } = dropdown_store;
    const { doc_types_sub_types_list } = storeToRefs(dropdown_store);

    return {
      doc_types_sub_types_list,
      selected_record,
      getScripts,
      fillDocTypeAndSubTypesListIfEmpty,
      doc_type_key,
      sub_doc_type_key,
      configId: 0,
      script_list,
      processing,
      deleteConfirmation: ref(false),
      scriptCopyDialog: ref(false),
    };
  },
});
</script>

