<template>
  <div class="search-filter-bar">
    <!-- Top Row: Search + Quick Filters + New Button -->
    <div class="search-filter-bar__top">
      <!-- Search Input with Filter Dropdown -->
      <q-input
        v-model="searchQuery"
        outlined
        dense
        :placeholder="$t('search_scripts_placeholder')"
        class="search-filter-bar__search"
        @update:model-value="handleSearchInput"
      >
        <template v-slot:prepend>
          <q-icon name="search" />
        </template>
        <template v-slot:append>
          <q-icon
            v-if="searchQuery"
            name="close"
            @click="clearSearch"
            class="cursor-pointer q-mr-sm"
          />
          <!-- Filter Button with Dropdown -->
          <q-btn flat dense round icon="tune" :color="hasActiveFilters ? 'primary' : 'grey-7'">
            <q-badge v-if="activeFilterCount > 0" color="primary" floating>
              {{ activeFilterCount }}
            </q-badge>
            <q-menu
              anchor="bottom start"
              self="top left"
              :offset="[404, 10]"
              style="width: 450px; min-height: 250px"
            >
              <div class="filter-menu__content">
                <!-- Row 1: Trigger Event (full width since it has many options) -->
                <div class="filter-item">
                  <span class="filter-label">{{ $t('trigger_event') }}</span>
                  <q-select
                    v-model="localFilters.triggers"
                    :options="triggerOptions"
                    outlined
                    dense
                    multiple
                    use-chips
                    emit-value
                    map-options
                    clearable
                    class="filter-select"
                    :placeholder="$t('select')"
                  />
                </div>

                <!-- Row 2: Date range side by side -->
                <div class="filter-row-inline">
                  <div class="filter-item">
                    <span class="filter-label">{{ $t('modified_from') }}</span>
                    <q-input
                      v-model="localFilters.dateFrom"
                      outlined
                      dense
                      clearable
                      readonly
                      class="filter-input"
                      :placeholder="$t('select')"
                    >
                      <template v-slot:append>
                        <q-icon name="event" class="cursor-pointer">
                          <q-popup-proxy cover transition-show="scale" transition-hide="scale">
                            <q-date
                              v-model="localFilters.dateFrom"
                              mask="YYYY-MM-DD"
                            >
                              <div class="row items-center justify-end">
                                <q-btn v-close-popup :label="$t('close')" color="primary" flat />
                              </div>
                            </q-date>
                          </q-popup-proxy>
                        </q-icon>
                      </template>
                    </q-input>
                  </div>

                  <div class="filter-item">
                    <span class="filter-label">{{ $t('modified_to') }}</span>
                    <q-input
                      v-model="localFilters.dateTo"
                      outlined
                      dense
                      clearable
                      readonly
                      class="filter-input"
                      :placeholder="$t('select')"
                    >
                      <template v-slot:append>
                        <q-icon name="event" class="cursor-pointer">
                          <q-popup-proxy cover transition-show="scale" transition-hide="scale">
                            <q-date
                              v-model="localFilters.dateTo"
                              mask="YYYY-MM-DD"
                            >
                              <div class="row items-center justify-end">
                                <q-btn v-close-popup :label="$t('close')" color="primary" flat />
                              </div>
                            </q-date>
                          </q-popup-proxy>
                        </q-icon>
                      </template>
                    </q-input>
                  </div>
                </div>

                <!-- Action Buttons -->
                <div class="filter-actions">
                  <q-btn
                    flat
                    dense
                    :label="$t('clear_filters')"
                    color="negative"
                    @click="clearAllFilters"
                    class="text-capitalize"
                  />
                  <q-btn
                    unelevated
                    dense
                    :label="$t('apply')"
                    color="primary"
                    @click="applyFilters"
                    v-close-popup
                    class="text-capitalize"
                  />
                </div>
              </div>
            </q-menu>
          </q-btn>
        </template>
      </q-input>

      <!-- Quick Filters (All/Active/Inactive) -->
      <q-btn-toggle
        v-model="localQuickFilter"
        @update:model-value="$emit('update:quick-filter', $event)"
        no-caps
        unelevated
        toggle-color="primary"
        color="grey-3"
        text-color="grey-8"
        :options="quickFilterOptions"
        class="quick-filter-toggle"
      />

      <!-- Sort Controls (icon/text with tooltips) -->
      <q-btn-group v-if="sortOptions.length > 0" unelevated class="sort-toggle">
        <q-btn
          v-for="option in sortOptions"
          :key="option.value"
          :icon="option.icon"
          :color="sortBy === option.value ? 'primary' : 'grey-3'"
          :text-color="sortBy === option.value ? 'white' : 'grey-8'"
          unelevated
          dense
          @click="$emit('update:sort-by', option.value)"
        >
          <span v-if="option.text" class="sort-btn-text">{{ option.text }}</span>
          <q-tooltip>{{ option.label }}</q-tooltip>
        </q-btn>
      </q-btn-group>

      <!-- New Button -->
      <q-btn
        unelevated
        icon="add"
        :label="$t('new')"
        color="primary"
        class="new-btn"
        @click="$emit('create-new')"
      />
    </div>

    <!-- Active Filter Chips -->
    <div v-if="hasActiveFilters" class="search-filter-bar__active-filters">
      <q-chip
        v-for="(filter, index) in activeFilterChips"
        :key="index"
        removable
        dense
        color="primary"
        text-color="white"
        @remove="removeFilter(filter.key)"
        size="sm"
      >
        {{ filter.label }}
      </q-chip>

      <q-btn
        flat
        dense
        size="sm"
        :label="$t('clear_all')"
        color="negative"
        @click="clearAllFilters"
        class="q-ml-xs"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch, onMounted, onUnmounted } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { debounce } from 'quasar';
import { i18n } from 'src/boot/i18n';
import { useDropdownStore } from 'src/store/main';

export interface Filters {
  docTypes: string[];
  triggers: string[];
  languages: string[];
  dateFrom: string | null;
  dateTo: string | null;
}

export interface SortOption {
  label: string;
  value: string;
  icon?: string;
  text?: string;
}

export default defineComponent({
  name: 'SearchFilterBar',
  props: {
    modelValue: {
      type: String,
      default: '',
    },
    quickFilter: {
      type: String,
      default: 'all',
    },
    filters: {
      type: Object as () => Filters,
      default: () => ({
        docTypes: [],
        triggers: [],
        languages: [],
        dateFrom: null,
        dateTo: null,
      }),
    },
    // docTypeOptions prop removed - not needed since page is already doc-type specific
    totalCount: {
      type: Number,
      default: 0,
    },
    activeCount: {
      type: Number,
      default: 0,
    },
    inactiveCount: {
      type: Number,
      default: 0,
    },
    sortBy: {
      type: String,
      default: 'modified-desc',
    },
    sortOptions: {
      type: Array as () => SortOption[],
      default: () => [],
    },
  },
  emits: [
    'update:model-value',
    'update:quick-filter',
    'update:filters',
    'update:sort-by',
    'create-new',
  ],
  setup(props, { emit }) {
    const dropdownStore = useDropdownStore();
    const searchQuery = ref(props.modelValue);
    const localFilters = ref<Filters>({ ...props.filters });
    const localQuickFilter = ref(props.quickFilter);

    // Watch for external changes to filters
    watch(
      () => props.filters,
      (newFilters) => {
        localFilters.value = { ...newFilters };
      },
      { deep: true },
    );

    // Watch for external changes to quickFilter prop
    watch(
      () => props.quickFilter,
      (newQuickFilter) => {
        localQuickFilter.value = newQuickFilter;
      },
    );

    const quickFilterOptions = computed(() => [
      {
        label: `${i18n.t('all')} (${props.totalCount})`,
        value: 'all',
      },
      {
        label: `${i18n.t('active')} (${props.activeCount})`,
        value: 'active',
      },
      {
        label: `${i18n.t('inactive')} (${props.inactiveCount})`,
        value: 'inactive',
      },
    ]);

    // Use trigger options from dropdown store with translation keys (script.trigger_name)
    const triggerOptions = computed(() =>
      dropdownStore.script_trigger_list.map((trigger: string) => ({
        label: i18n.t(`script.${trigger}`.toLowerCase()),
        value: trigger,
      })),
    );

    const hasActiveFilters = computed(() => {
      return (
        localFilters.value.triggers.length > 0 ||
        localFilters.value.dateFrom !== null ||
        localFilters.value.dateTo !== null
      );
    });

    const activeFilterCount = computed(() => {
      let count = 0;
      if (localFilters.value.triggers.length > 0)
        count += localFilters.value.triggers.length;
      if (localFilters.value.dateFrom) count++;
      if (localFilters.value.dateTo) count++;
      return count;
    });

    const activeFilterChips = computed(() => {
      const chips: Array<{ key: string; label: string }> = [];

      // Triggers
      localFilters.value.triggers.forEach((trigger) => {
        const option = triggerOptions.value.find(
          (opt) => opt.value === trigger,
        );
        chips.push({
          key: `trigger:${trigger}`,
          label: option?.label || trigger,
        });
      });

      // Date range
      if (localFilters.value.dateFrom) {
        chips.push({
          key: 'dateFrom',
          label: `${i18n.t('from')}: ${localFilters.value.dateFrom}`,
        });
      }
      if (localFilters.value.dateTo) {
        chips.push({
          key: 'dateTo',
          label: `${i18n.t('to')}: ${localFilters.value.dateTo}`,
        });
      }

      return chips;
    });

    // Debounced search input handler
    const handleSearchInput = debounce((value: string) => {
      emit('update:model-value', value);
    }, 300);

    const clearSearch = () => {
      searchQuery.value = '';
      emit('update:model-value', '');
    };

    const removeFilter = (key: string) => {
      const [type, value] = key.split(':');

      switch (type) {
        case 'trigger':
          localFilters.value.triggers = localFilters.value.triggers.filter(
            (t: string) => t !== value,
          );
          break;
        case 'dateFrom':
          localFilters.value.dateFrom = null;
          break;
        case 'dateTo':
          localFilters.value.dateTo = null;
          break;
      }

      emit('update:filters', localFilters.value);
    };

    const clearAllFilters = () => {
      localFilters.value = {
        docTypes: [],
        triggers: [],
        languages: [],
        dateFrom: null,
        dateTo: null,
      };
      emit('update:filters', localFilters.value);
    };

    const applyFilters = () => {
      emit('update:filters', localFilters.value);
    };

    return {
      searchQuery,
      localFilters,
      localQuickFilter,
      quickFilterOptions,
      triggerOptions,
      hasActiveFilters,
      activeFilterCount,
      activeFilterChips,
      handleSearchInput,
      clearSearch,
      removeFilter,
      clearAllFilters,
      applyFilters,
    };
  },
});
</script>

