<template>
  <div class="empty-state">
    <div class="empty-state__content">
      <!-- Icon/Illustration -->
      <div class="empty-state__icon">
        <q-icon :name="icon" :color="iconColor" size="120px" />
      </div>

      <!-- Title -->
      <div class="empty-state__title">
        {{ title }}
      </div>

      <!-- Description -->
      <div class="empty-state__description">
        {{ description }}
      </div>

      <!-- Primary Action -->
      <div v-if="showAction" class="empty-state__action">
        <q-btn
          unelevated
          :icon="actionIcon"
          :label="actionLabel"
          color="primary"
          size="lg"
          @click="$emit('action-click')"
          class="q-px-xl"
        />
      </div>

      <!-- Secondary Link -->
      <div v-if="showHelp" class="empty-state__help">
        <a
          :href="helpLink"
          target="_blank"
          rel="noopener noreferrer"
          class="text-primary"
        >
          {{ helpText }} →
        </a>
      </div>

      <!-- Additional Info -->
      <div v-if="additionalInfo" class="empty-state__additional">
        <q-card flat bordered class="q-pa-md">
          <div class="text-body2 text-grey-8">
            {{ additionalInfo }}
          </div>
        </q-card>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { getLink } from 'src/utils/helpLinks';

export default defineComponent({
  name: 'EnhancedEmptyState',
  props: {
    icon: {
      type: String,
      default: 'description',
    },
    iconColor: {
      type: String,
      default: 'grey-5',
    },
    title: {
      type: String,
      required: true,
    },
    description: {
      type: String,
      required: true,
    },
    showAction: {
      type: Boolean,
      default: true,
    },
    actionIcon: {
      type: String,
      default: 'add',
    },
    actionLabel: {
      type: String,
      default: 'Create Script',
    },
    showHelp: {
      type: Boolean,
      default: true,
    },
    helpText: {
      type: String,
      default: 'Learn more about scripts',
    },
    helpLinkName: {
      type: String,
      default: '',
    },
    additionalInfo: {
      type: String,
      default: '',
    },
  },
  emits: ['action-click'],
  setup(props) {
    const helpLink = computed(() => {
      return getLink(props.helpLinkName);
    });

    return {
      helpLink,
    };
  },
});
</script>

